import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.7He2WLS4.js";const g=JSON.parse('{"title":"What is NectoProxy?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1772297611000}'),n={name:"guide/index.md"};function s(i,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="what-is-nectoproxy" tabindex="-1">What is NectoProxy? <a class="header-anchor" href="#what-is-nectoproxy" aria-label="Permalink to &quot;What is NectoProxy?&quot;">​</a></h1><p>NectoProxy is a powerful, open-source <strong>man-in-the-middle (MITM) proxy</strong> for intercepting, inspecting, modifying, and replaying HTTP/HTTPS traffic. It ships with a modern <strong>Web UI</strong> built on React, giving you a visual dashboard to debug network requests in real time -- no native app installation required.</p><p>Think of it as a <strong>free, cross-platform alternative</strong> to Charles Proxy and Fiddler, purpose-built for the modern development workflow.</p><h2 id="who-is-nectoproxy-for" tabindex="-1">Who is NectoProxy For? <a class="header-anchor" href="#who-is-nectoproxy-for" aria-label="Permalink to &quot;Who is NectoProxy For?&quot;">​</a></h2><p>NectoProxy is designed for anyone who needs deep visibility into HTTP traffic:</p><ul><li><strong>Web Developers</strong> -- Debug API calls, inspect headers, troubleshoot CORS issues, and mock responses during frontend development.</li><li><strong>Mobile Developers</strong> -- Proxy iOS and Android device traffic through NectoProxy to inspect network requests from native apps.</li><li><strong>QA Engineers</strong> -- Simulate network conditions, inject failures, and verify application behavior under adverse conditions.</li><li><strong>Security Researchers</strong> -- Analyze request/response patterns, scan for security vulnerabilities, and inspect TLS handshake details.</li><li><strong>Backend Engineers</strong> -- Trace requests through microservices, compare API versions, and generate client code from captured traffic.</li></ul><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="traffic-inspection" tabindex="-1">Traffic Inspection <a class="header-anchor" href="#traffic-inspection" aria-label="Permalink to &quot;Traffic Inspection&quot;">​</a></h3><p>Intercept and inspect every HTTP and HTTPS request flowing through the proxy. NectoProxy performs MITM decryption by generating per-domain SSL certificates on the fly, signed by its own root CA. Traffic streams into the Web UI in real time via WebSocket, with a virtualized list capable of handling thousands of entries.</p><h3 id="rules-engine" tabindex="-1">Rules Engine <a class="header-anchor" href="#rules-engine" aria-label="Permalink to &quot;Rules Engine&quot;">​</a></h3><p>The rules engine provides <strong>8 built-in actions</strong> for controlling traffic without writing code:</p><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Mock</strong></td><td>Return custom responses without hitting the upstream server</td></tr><tr><td><strong>Block</strong></td><td>Reject matching requests entirely</td></tr><tr><td><strong>Modify Request</strong></td><td>Add, remove, or change headers, query parameters, and body content</td></tr><tr><td><strong>Modify Response</strong></td><td>Alter status codes, response headers, or response bodies</td></tr><tr><td><strong>Map Local</strong></td><td>Serve files directly from your local filesystem</td></tr><tr><td><strong>Map Remote</strong></td><td>Redirect requests to a different URL</td></tr><tr><td><strong>Delay</strong></td><td>Introduce artificial latency with configurable variance</td></tr><tr><td><strong>Throttle</strong></td><td>Limit bandwidth to simulate slow connections</td></tr></tbody></table><h3 id="breakpoints" tabindex="-1">Breakpoints <a class="header-anchor" href="#breakpoints" aria-label="Permalink to &quot;Breakpoints&quot;">​</a></h3><p>Pause any request or response mid-flight for <strong>manual inspection and modification</strong> before forwarding. Breakpoints let you edit headers, bodies, and status codes interactively -- ideal for testing edge cases without modifying application code.</p><h3 id="network-conditioning" tabindex="-1">Network Conditioning <a class="header-anchor" href="#network-conditioning" aria-label="Permalink to &quot;Network Conditioning&quot;">​</a></h3><p>Simulate real-world network conditions by applying bandwidth limits, latency, and packet loss. Choose from built-in profiles (3G, slow Wi-Fi, satellite) or define custom profiles to match specific environments.</p><h3 id="code-generation" tabindex="-1">Code Generation <a class="header-anchor" href="#code-generation" aria-label="Permalink to &quot;Code Generation&quot;">​</a></h3><p>Generate equivalent code from any captured request in <strong>8 languages and tools</strong>:</p><ul><li>cURL</li><li>Python (requests)</li><li>Node.js (fetch / axios)</li><li>Go (net/http)</li><li>PHP (cURL)</li><li>Rust (reqwest)</li><li>And more</li></ul><h3 id="security-scanning" tabindex="-1">Security Scanning <a class="header-anchor" href="#security-scanning" aria-label="Permalink to &quot;Security Scanning&quot;">​</a></h3><p>Run automated security scans against captured traffic to identify potential vulnerabilities, insecure headers, mixed content issues, and other common security concerns.</p><h3 id="additional-capabilities" tabindex="-1">Additional Capabilities <a class="header-anchor" href="#additional-capabilities" aria-label="Permalink to &quot;Additional Capabilities&quot;">​</a></h3><ul><li><strong>HAR Import/Export</strong> -- Share and analyze traffic using the standard HTTP Archive format.</li><li><strong>Request Comparison</strong> -- Diff two captured requests side by side to spot differences.</li><li><strong>Request Replay</strong> -- Re-send any captured request and compare the new response against the original.</li><li><strong>Dashboard &amp; Analytics</strong> -- Visualize traffic patterns with charts and statistics.</li><li><strong>Session Management</strong> -- Organize captured traffic into named sessions.</li><li><strong>Filtering</strong> -- Filter by HTTP method, status code, URL pattern, host, or content type.</li><li><strong>Command Palette</strong> -- Quick keyboard-driven access to all features.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>NectoProxy is structured as a <strong>monorepo</strong> with clearly separated packages:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nectoproxy/</span></span>
<span class="line"><span>├── apps/</span></span>
<span class="line"><span>│   ├── cli/            # CLI entry point (the published npm package)</span></span>
<span class="line"><span>│   └── web/            # React Web UI (bundled into the CLI at build time)</span></span>
<span class="line"><span>├── packages/</span></span>
<span class="line"><span>│   ├── core/           # MITM proxy engine (net/tls/http)</span></span>
<span class="line"><span>│   ├── server/         # Express REST API + Socket.IO real-time layer</span></span>
<span class="line"><span>│   ├── storage/        # SQLite database via better-sqlite3 + Drizzle ORM</span></span>
<span class="line"><span>│   ├── certs/          # SSL/TLS certificate generation using node-forge</span></span>
<span class="line"><span>│   └── shared/         # TypeScript type definitions shared across packages</span></span></code></pre></div><h3 id="how-the-pieces-fit-together" tabindex="-1">How the Pieces Fit Together <a class="header-anchor" href="#how-the-pieces-fit-together" aria-label="Permalink to &quot;How the Pieces Fit Together&quot;">​</a></h3><ol><li>The <strong>CLI</strong> (<code>apps/cli</code>) is the user-facing entry point. When you run <code>nectoproxy start</code>, it orchestrates the proxy engine, API server, and Web UI.</li><li>The <strong>Core</strong> package (<code>packages/core</code>) implements the MITM proxy using native Node.js <code>http</code>, <code>net</code>, and <code>tls</code> modules. It intercepts both HTTP and HTTPS (via CONNECT tunneling).</li><li>The <strong>Certs</strong> package (<code>packages/certs</code>) generates the root CA certificate and dynamically creates per-domain certificates signed by that CA.</li><li>The <strong>Server</strong> package (<code>packages/server</code>) exposes a REST API (Express) and real-time events (Socket.IO) that the Web UI consumes.</li><li>The <strong>Storage</strong> package (<code>packages/storage</code>) persists sessions, captured traffic, rules, and settings to a local SQLite database.</li><li>The <strong>Web</strong> app (<code>apps/web</code>) is a React 18 SPA that provides the dashboard, traffic viewer, rules editor, and all visual tooling.</li></ol><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td><strong>Runtime</strong></td><td>Node.js 20+, TypeScript</td></tr><tr><td><strong>Monorepo</strong></td><td>pnpm workspaces + Turborepo</td></tr><tr><td><strong>Proxy Engine</strong></td><td>Native Node.js <code>http</code> / <code>net</code> / <code>tls</code>, node-forge</td></tr><tr><td><strong>Database</strong></td><td>better-sqlite3 + Drizzle ORM</td></tr><tr><td><strong>API</strong></td><td>Express + Socket.IO</td></tr><tr><td><strong>Web UI</strong></td><td>React 18, Vite, TailwindCSS, Zustand, React Query</td></tr></tbody></table><h2 id="open-source" tabindex="-1">Open Source <a class="header-anchor" href="#open-source" aria-label="Permalink to &quot;Open Source&quot;">​</a></h2><p>NectoProxy is released under the <strong>MIT License</strong> and is fully open source. It is created and maintained by <strong>Sitharaj Seenivasan</strong>.</p><ul><li><strong>Repository</strong>: <a href="https://github.com/sitharaj88/nectoproxy" target="_blank" rel="noreferrer">github.com/sitharaj88/nectoproxy</a></li><li><strong>Author</strong>: <a href="https://sitharaj.in" target="_blank" rel="noreferrer">sitharaj.in</a></li><li><strong>License</strong>: MIT</li></ul><div class="tip custom-block"><p class="custom-block-title">Community Contributions Welcome</p><p>NectoProxy is open to contributions of all kinds -- bug reports, feature requests, documentation improvements, and code contributions. Check the repository for contribution guidelines.</p></div>`,34)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
